        closed = -1
        while i < n:
            c = np[i]
            if c == '\\':
                if i + 1 >= n:
                    raise UErr()
                nx = np[i + 1]
                if not (nx == '\t' or (0x21 <= ord(nx) <= 0x7e)):
                    raise UErr()
